-- Phase 6 read-only verification. Execute after 01_apply.sql.
SET @srp6v_tables := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name IN ('course_offering_minimum_enrollment_reviews','course_offering_minimum_enrollment_events','student_registration_replacement_requests','student_registration_replacement_items','student_registration_replacement_events') AND engine='InnoDB');
SET @srp6v_owned := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name IN ('course_offering_minimum_enrollment_reviews','course_offering_minimum_enrollment_events','student_registration_replacement_requests','student_registration_replacement_items','student_registration_replacement_events') AND table_comment LIKE 'Owned by semester-registration-minimum-cancellation-replacement-phase6%');
SET @srp6v_columns := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='course_offering_minimum_enrollment_reviews' AND column_name IN ('course_offering_minimum_enrollment_review_id','semester_offering_request_id','course_offering_id','academic_year_id','semester_id','minimum_enrollment_snapshot','enrolled_count_snapshot','finalization_deadline_at','finalized_at','status','dean_recommendation','dean_user_id','dean_notes','dean_recommended_at','scientific_decision','scientific_user_id','scientific_notes','scientific_decided_at','course_offering_closure_request_id','continued_at','cancelled_at','superseded_at','affected_registration_count','created_at','updated_at')) OR (table_name='course_offering_minimum_enrollment_events' AND column_name IN ('course_offering_minimum_enrollment_event_id','course_offering_minimum_enrollment_review_id','event_type','actor_user_id','notes','created_at')) OR (table_name='student_registration_replacement_requests' AND column_name IN ('student_registration_replacement_request_id','academic_calendar_event_id','student_id','academic_year_id','semester_id','status','submission_version','current_slot','student_notes','advisor_user_id','advisor_notes','first_submitted_at','last_submitted_at','reviewed_at','approved_at','expired_at','superseded_at','materialized_at','registered_hours_before_approval','replacement_hours_at_approval','projected_hours_at_approval','max_allowed_hours_at_approval','remaining_hours_after_approval','created_at','updated_at')) OR (table_name='student_registration_replacement_items' AND column_name IN ('student_registration_replacement_item_id','student_registration_replacement_request_id','source_minimum_enrollment_review_id','source_student_course_registration_id','replacement_course_offering_id','materialized_student_course_registration_id','source_consumed_slot','created_at','updated_at')) OR (table_name='student_registration_replacement_events' AND column_name IN ('student_registration_replacement_event_id','student_registration_replacement_request_id','event_type','actor_user_id','from_status','to_status','submission_version','notes','created_at'))));
SET @srp6v_pk := (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name IN ('course_offering_minimum_enrollment_reviews','course_offering_minimum_enrollment_events','student_registration_replacement_requests','student_registration_replacement_items','student_registration_replacement_events') AND constraint_type='PRIMARY KEY');
SET @srp6v_unique := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND non_unique=0 AND index_name IN ('uq_comer_request','uq_comer_offering','uq_comer_closure','uq_srrpr_current','uq_srrpi_source_in_request','uq_srrpi_target_in_request','uq_srrpi_source_consumed'));
SET @srp6v_checks := (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema='alrowad_uni_rust' AND constraint_type='CHECK' AND constraint_name IN ('chk_comer_snapshots','chk_comer_status','chk_comer_dean','chk_comer_dean_status','chk_comer_scientific','chk_comer_terminal','chk_comee_type','chk_srrpr_status','chk_srrpr_version','chk_srrpr_current','chk_srrpr_submission','chk_srrpr_return','chk_srrpr_terminal','chk_srrpr_snapshot','chk_srrpi_consumed','chk_srrpe_type'));
SET @srp6v_fks := (SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema='alrowad_uni_rust' AND constraint_name IN ('fk_comer_semester_request','fk_comer_offering','fk_comer_year','fk_comer_semester','fk_comer_dean','fk_comer_scientific','fk_comer_closure','fk_comee_review','fk_comee_actor','fk_srrpr_event','fk_srrpr_student','fk_srrpr_year','fk_srrpr_semester','fk_srrpr_advisor','fk_srrpi_request','fk_srrpi_review','fk_srrpi_source','fk_srrpi_target','fk_srrpi_materialized','fk_srrpe_request','fk_srrpe_actor') AND update_rule='RESTRICT' AND delete_rule='RESTRICT');
SET @srp6v_source_consumed := (SELECT COUNT(*) FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_replacement_items' AND non_unique=0 GROUP BY index_name) i WHERE (index_name='uq_srrpi_source_consumed' AND cols='source_student_course_registration_id,source_consumed_slot') OR (index_name='uq_srrpi_source_in_request' AND cols='student_registration_replacement_request_id,source_student_course_registration_id') OR (index_name='uq_srrpi_target_in_request' AND cols='student_registration_replacement_request_id,replacement_course_offering_id'));
SET @srp6v_cancelled := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`registration_statuses` WHERE status_code='cancelled' AND status_name='ملغى لعدم اكتمال الحد الأدنى' AND is_active=1);
SET @srp6v_type := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_calendar_event_types` r JOIN `alrowad_uni_rust`.`academic_calendar_event_types` s ON s.event_type_code='course_registration' WHERE r.event_type_code='course_registration_replacement' AND r.name_ar='استبدال المقررات الملغاة' AND r.event_type_kind=s.event_type_kind AND r.default_is_enforcement=s.default_is_enforcement AND r.is_active=s.is_active);
SET @srp6v_permissions := (SELECT COUNT(DISTINCT permission_code) FROM `alrowad_uni_rust`.`permissions` WHERE is_active=1 AND permission_code IN ('course_offerings.semester_governance.view','course_offerings.semester_governance.manage','course_offerings.semester_governance.review_scientific','course_offerings.closure.view','course_offerings.closure.request','course_offerings.closure.review_scientific','course_offerings.closure.review_administrative','registration_requests.view','registration_requests.review'));
SET @srp6v_pres := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`organizational_units` WHERE unit_code='PRES' AND is_active=1);
SET @srp6v_data := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`student_registration_replacement_items` WHERE (source_consumed_slot IS NULL)<>(materialized_student_course_registration_id IS NULL));
SET @srp6v_pass := (@srp6v_tables=5 AND @srp6v_owned=5 AND @srp6v_columns=74 AND @srp6v_pk=5 AND @srp6v_unique=13 AND @srp6v_checks=16 AND @srp6v_fks=21 AND @srp6v_source_consumed=3 AND @srp6v_cancelled=1 AND @srp6v_type=1 AND @srp6v_permissions=9 AND @srp6v_pres=1 AND @srp6v_data=0);
SELECT 'STRUCTURE' report_section,IF(@srp6v_tables=5 AND @srp6v_owned=5 AND @srp6v_columns=74 AND @srp6v_pk=5,'PASS','FAIL') result,CONCAT('tables=',@srp6v_tables,'/5; columns=',@srp6v_columns,'/74; pk=',@srp6v_pk,'/5') detail;
SELECT 'CONSTRAINTS' report_section,IF(@srp6v_source_consumed=3 AND @srp6v_checks=16 AND @srp6v_fks=21,'PASS','FAIL') result,CONCAT('source_uniques=',@srp6v_source_consumed,'/3; checks=',@srp6v_checks,'/16; fks=',@srp6v_fks,'/21') detail;
SELECT 'REFERENCE_CODES' report_section,IF(@srp6v_cancelled=1 AND @srp6v_type=1,'PASS','FAIL') result,CONCAT('cancelled=',@srp6v_cancelled,'; replacement_type=',@srp6v_type) detail;
SELECT 'RBAC_AND_SCOPE' report_section,IF(@srp6v_permissions=9 AND @srp6v_pres=1,'PASS','FAIL') result,CONCAT('existing_permissions=',@srp6v_permissions,'/9; PRES=',@srp6v_pres,'/1') detail;
SELECT 'OVERALL' report_section,IF(@srp6v_pass,'PASS','FAIL') result;
